const std = @import("std");

const Node = struct {
    key: i32,
    height: i32,
    left: ?*Node,
    right: ?*Node,
};

fn height(n: ?*Node) i32 { return if (n) |node| node.height else 0; }
fn max(a: i32, b: i32) i32 { return if (a > b) a else b; }

fn rotateRight(y: *Node) *Node {
    const x = y.left.?;
    y.left = x.right;
    x.right = y;
    y.height = 1 + max(height(y.left), height(y.right));
    x.height = 1 + max(height(x.left), height(x.right));
    return x;
}

fn rotateLeft(x: *Node) *Node {
    const y = x.right.?;
    x.right = y.left;
    y.left = x;
    x.height = 1 + max(height(x.left), height(x.right));
    y.height = 1 + max(height(y.left), height(y.right));
    return y;
}

pub fn main() !void {
    var n1 = Node{ .key = 10, .height = 3, .left = undefined, .right = undefined };
    var n2 = Node{ .key = 20, .height = 2, .left = undefined, .right = undefined };
    var n3 = Node{ .key = 30, .height = 1, .left = undefined, .right = undefined };
    n1.right = &n2;
    n2.right = &n3;

    var root = &n1;
    root = rotateLeft(root);

    std.debug.print("Root: {}\n", .{root.key});
    std.debug.print("Left: {}\n", .{root.left.?.key});
    std.debug.print("Right: {}\n", .{root.right.?.key});
}

